        sessions.put(id, s);
        return s;
    }

    public Optional<Session> get(String id) {
        return Optional.ofNullable(sessions.get(id));
    }

    public Optional<Session> renew(String id) {
        return sessions.computeIfPresent(id, (k, old) -> {
            if (old.expiresAt().isBefore(Instant.now())) return null;
            return new Session(old.id(), old.userId(), Instant.now().plus(30, TimeUnit.MINUTES), old.attributes());
        });
    }

    public Optional<Session> updateAttributes(String id, Function<Map<String,String>, Map<String,String>> updater) {
        return sessions.computeIfPresent(id, (k, old) -> {
            Map<String,String> next = updater.apply(old.attributes());
            return new Session(old.id(), old.userId(), old.expiresAt(), Map.copyOf(next));
        });
    }

    public void invalidate(String id) { sessions.remove(id); }
}

