import java.time.Duration;
import java.time.Instant;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Function;

public final class SessionStore {
    private static final Duration TTL = Duration.ofMinutes(30);
    private final ConcurrentHashMap<String, Session> sessions = new ConcurrentHashMap<>();
    private final AtomicLong idCounter = new AtomicLong();

    public record Session(String id, String userId, Instant expiresAt, Map<String, String> attributes) {
        public Session withAttributes(Map<String, String> next) {
            return new Session(id, userId, expiresAt, Map.copyOf(next));
        }
    }

    public Session create(String userId) {
        String id = "sess-" + idCounter.incrementAndGet();
        Session session = new Session(id, userId, Instant.now().plus(TTL), Map.of());
        sessions.put(id, session);
        return session;
    }

    public Optional<Session> get(String id) {
        return Optional.ofNullable(sessions.get(id));
    }

    public Optional<Session> renew(String id) {
        return sessions.computeIfPresent(id, (key, old) -> {
            if (old.expiresAt().isBefore(Instant.now())) {
                return null;
            }
            return new Session(old.id(), old.userId(), Instant.now().plus(TTL), old.attributes());
        });
    }

    public Optional<Session> updateAttributes(String id, Function<Map<String, String>, Map<String, String>> updater) {
        return sessions.computeIfPresent(id, (key, old) -> {
            Map<String, String> next = updater.apply(old.attributes());
            return new Session(old.id(), old.userId(), old.expiresAt(), Map.copyOf(next));
        });
    }

    public void invalidate(String id) {
        sessions.remove(id);
    }
}

